import type { TabBadgeProps } from "./tab/tab.types";

import { forwardRef } from "react";
import { Badge } from "@components/badge";
import { clsx } from "clsx";

import { TabClasses } from "./tab/tab.styles";

export const TabBadge = forwardRef<HTMLDivElement, TabBadgeProps>(
  ({ className, ...props }, ref) => {
    const badgeClasses = clsx(TabClasses.badge, className);

    return <Badge ref={ref} className={badgeClasses} variant="info" {...props} />;
  },
);

TabBadge.displayName = "Tab.Badge";
